"""Threefile data-only Aha replay; standardlibrary, no subprocess/native/network."""
import pathlib,json,hashlib,tarfile,tempfile,re
D=pathlib.Path(__file__).resolve().parent
sha=lambda b:hashlib.sha256(b).hexdigest()
manifestPath=D/'timing-proof.manifest.json'
assert sha(manifestPath.read_bytes())=='c67f9a130288dd28049b2f58c50b2e470379ba710f04580964549f1db09d2ce0','manifest envelope hash'
m=json.loads(manifestPath.read_text());a=D/m['archive'];assert a.stat().st_size==m['archiveBytes'] and sha(a.read_bytes())==m['archiveSHA256'],'archive envelope hash'
assert len(m['paths'])<=1200 and m['uncompressedSelectedBytes']<=10485760
with tempfile.TemporaryDirectory(prefix='amu-aha-offline-')as td:
 P=pathlib.Path(td);objects={}
 with tarfile.open(a,'r:gz')as tf:
  for info in tf.getmembers():
   assert info.isfile()and info.name.startswith('objects/')and len(info.name)==72 and info.size<=10485760
   b=tf.extractfile(info).read();key=info.name[8:];assert sha(b)==key and key not in objects;objects[key]=b
 assert len(objects)==m['objects']
 for name,v in m['paths'].items():
  path=pathlib.PurePosixPath(name);assert not path.is_absolute() and '..'not in path.parts
  b=objects[v['object']];assert len(b)==v['bytes'];f=P/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes(b)
 Q=P/'team-charged-aha-remote-prep/package/aha-mont64';header=(Q/'immutable-header.h').read_text()
 for name,file in [('known_baseline','baseline.bin'),('known_candidate','candidate.bin'),('timing_known_c_bytes','c.dylib')]:
  match=re.search(r'\b'+name+r'\[\]\s*=\s*\{([^}]*)\}',header);assert match
  assert bytes(int(x)for x in match[1].split(',')if x.strip())==(Q/file).read_bytes()
 assert '#define KEXE_EMBEDDED_REQUIRED_HOST_FEATURES 6ULL' in header
 assert 'timing_known_offsets[] = {3456,3508}' in header and '#define TIMING_KNOWN_C_SYMBOL "bench"'in header
 def run(source,label):
  output=P/('offline-output-'+label);output.mkdir()
  source=source.replace("P=pathlib.Path('/private/tmp/amu-aes-resident-fuel-20261007')","P=pathlib.Path("+repr(str(P))+")").replace('D=pathlib.Path(__file__).parent','D=pathlib.Path('+repr(str(output))+')')
  ns={'__name__':'offline_recompute','__file__':str(output/'embedded.py')};exec(compile(source,label,'exec'),ns)
  return json.loads((output/'report.json').read_text())
 semantic=run(SEMANTIC_REVIEW,'semantic')
 timing=run(TIMING_REVIEW,'timing')
 frozen=json.loads((P/'team-charged-aha-timing-results-independent/report.json').read_text());assert timing==frozen
 decision=json.loads((P/'root/charged-aha-timing-stage-decision.json').read_text())
 assert decision['summary']==timing['summary'] and decision['runnerProcesses']==149 and decision['acceptedTriples']==30 and decision['attemptedTriples']==47 and decision['rejectedTriples']==17
 assert decision['qualifiedGains']==['aha-mont64'] and decision['qualifiedCWins']==[] and decision['goalAchieved']is False and decision['productAdopted']is False and decision['officialEmbenchScore']is False
 print(json.dumps({'status':'PASS threefile offline data replay','semanticCalls':semantic['calls'],'timingRunnerProcesses':timing['runnerProcesses'],'acceptedTriples':30,'rejectedTriples':17,'summary':timing['summary'],'candidateTimeReductionPercent':timing['candidateTimeReductionPercent'],'headerArraysExact':3,'noNativeOrSolverExecution':True,'externalNativeProof':'referenced separately, not requalified'}))
